const program = [
  { label: 'loop', op: 'test-zero', reg: 'b', jumpToLabel: 'done' },
  { op: 'mod', dest: 'a', src1: 'a', src2: 'b' },
  { op: 'swap', reg1: 'a', reg2: 'b' },
  { op: 'jump', toLabel: 'loop' },
  { label: 'done', op: 'done' },
];

const labelTable = {};
program.forEach((instr, i) => {
  if (instr.label) labelTable[instr.label] = i;
});

const registers = { a: 12, b: 18 };
let pc = labelTable['loop'];
while (program[pc].op !== 'done') {
  const instr = program[pc];
  if (instr.op === 'test-zero') {
    pc = registers[instr.reg] === 0 ? labelTable[instr.jumpToLabel] : pc + 1;
  } else if (instr.op === 'mod') {
    registers[instr.dest] = registers[instr.src1] % registers[instr.src2];
    pc += 1;
  } else if (instr.op === 'swap') {
    [registers[instr.reg1], registers[instr.reg2]] = [registers[instr.reg2], registers[instr.reg1]];
    pc += 1;
  } else if (instr.op === 'jump') {
    pc = labelTable[instr.toLabel];
  }
}

console.log(registers.a);

