const program = [
  { label: 'loop', op: 'test-zero', reg: 'n', jumpToLabel: 'done' },
  { op: 'print' },
  { op: 'decrement', reg: 'n' },
  { op: 'jump', toLabel: 'loop' },
  { label: 'done', op: 'done' },
];
const labelTable = {};
program.forEach((instr, i) => { if (instr.label) labelTable[instr.label] = i; });

const registers = { n: 3 };
const output = [];
let pc = labelTable['loop'];
while (program[pc].op !== 'done') {
  const instr = program[pc];
  if (instr.op === 'test-zero') {
    pc = registers[instr.reg] === 0 ? labelTable[instr.jumpToLabel] : pc + 1;
  } else if (instr.op === 'print') {
    output.push(registers.n);
    pc += 1;
  } else if (instr.op === 'decrement') {
    registers[instr.reg] -= 1;
    pc += 1;
  } else if (instr.op === 'jump') {
    pc = labelTable[instr.toLabel];
  }
}

console.log(output);

